package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.type.TypeFactory;
import com.fasterxml.jackson.databind.util.ArrayBuilders;
import com.fasterxml.jackson.databind.util.ClassUtil;
import com.fasterxml.jackson.databind.util.LRUMap;
import java.io.*;
import java.lang.reflect.*;
import java.lang.reflect.ParameterizedType;
import java.lang.reflect.Type;
import java.math.*;
import java.util.*;
import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

/**
 * Unit tests for TypeFactory.constructType(Type type, JavaType contextType)
 */
public class TypeFactory_constructType_TriageGen0Test {

    private TypeFactory typeFactory;

    @Before
    public void setUp() {
        typeFactory = TypeFactory.defaultInstance();
    }

    @Test
    public void testConstructType_WithSimpleClass() {
        // Test with a simple class (String.class)
        Type type = String.class;
        JavaType contextType = typeFactory.constructSimpleType(String.class);

        JavaType result = typeFactory.constructType(type, contextType);

        assertNotNull(result);
        assertEquals(String.class, result.getRawClass());
    }

    @Test
    public void testConstructType_WithParameterizedType() {
        // Test with a parameterized type (List<String>)
        // We use a TypeReference or manual construction to get a ParameterizedType
        Type type = new TypeReference<List<String>>() {}.getType();
        JavaType contextType = typeFactory.constructSimpleType(Object.class);

        JavaType result = typeFactory.constructType(type, contextType);

        assertNotNull(result);
        assertEquals(List.class, result.getRawClass());
        // Verify that the type bindings from contextType are passed through to resolve the type
        assertEquals(String.class, result.containedType(0).getRawClass());
    }

    @Test
    public void testConstructType_WithMapContext() {
        // Test where contextType has specific bindings (e.g., Map<Integer, String>)
        // and the target type is a generic type that relies on those bindings

        // Create a context type: Map<Integer, String>
        JavaType contextType = typeFactory.constructMapType(Map.class, Integer.class, String.class);

        // Target type is just Map.class, but it should inherit bindings from context
        Type type = Map.class;

        JavaType result = typeFactory.constructType(type, contextType);

        assertNotNull(result);
        assertEquals(Map.class, result.getRawClass());
        // The result should have the bindings from the contextType
        assertEquals(contextType.getBindings(), result.getBindings());
    }

    @Test
    public void testConstructType_WithArrayType() {
        // Test with Array type
        Type type = String[].class;
        JavaType contextType = typeFactory.constructSimpleType(Object.class);

        JavaType result = typeFactory.constructType(type, contextType);

        assertNotNull(result);
        assertEquals(String[].class, result.getRawClass());
    }

    @Test
    public void testConstructType_WithWildcardType() {
        // Test with Wildcard (e.g., List<?>)
        // Since we can't easily instantiate WildcardType via reflection without complex setup, 
        // we use a TypeReference to simulate complex generic structures.
        Type type = new TypeReference<List<? extends Number>>() {}.getType();
        JavaType contextType = typeFactory.constructSimpleType(Object.class);

        JavaType result = typeFactory.constructType(type, contextType);

        assertNotNull(result);
        assertEquals(List.class, result.getRawClass());
    }

    @Test
    public void testConstructType_WithComplexNestedTypes() {
        // Test nested: Map<String, List<Integer>>
        Type type = new TypeReference<Map<String, List<Integer>>>() {}.getType();
        JavaType contextType = typeFactory.constructSimpleType(Object.class);

        JavaType result = typeFactory.constructType(type, contextType);

        assertNotNull(result);
        assertEquals(Map.class, result.getRawClass());

        JavaType valueType = result.containedType(1);
        assertNotNull(valueType);
        assertEquals(List.class, valueType.getRawClass());
        assertEquals(Integer.class, valueType.containedType(0).getRawClass());
    }

    /**
     * Helper class to facilitate Type generation via TypeReference
     */
    private static abstract class TypeReference<T> {
        public Type getType() {
            return ((ParameterizedType) getClass().getGenericSuperclass()).getActualTypeArguments()[0];
        }
    }
}
